public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }
    byte[] data = schema.toByteArray(message);
    int size = data.length;
    if (size > buffer.cacheSize()) {
        throw new IOException("Buffer size is too small");
    }
    buffer.writeVarint32(size);
    buffer.write(data, 0, size);
    out.write(buffer.getData(), buffer.offset(), buffer.size());
    buffer.clear();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message, buffer);
    int size = data.length;
    out.write(size >>> 24);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);
    out.write(data);
    return size + LinkedBuffer.size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    byte[] data = schema.toByteArray(message);
    int size = data.length;

    if (buffer.start != buffer.offset) {
        // Copy existing data to start of buffer
        System.arraycopy(buffer.buffer, buffer.offset, buffer.buffer, 0, buffer.start - buffer.offset);
        buffer.start -= buffer.offset;
        buffer.offset = 0;
    }

    if (buffer.length + 4 + size > buffer.capacity) {
        throw new IOException("Buffer overflow");
    }

    // Write the size of the message
    buffer.buffer[buffer.offset++] = (byte) ((size >>> 24) & 0xFF);
    buffer.buffer[buffer.offset++] = (byte) ((size >>> 16) & 0xFF);
    buffer.buffer[buffer.offset++] = (byte) ((size >>> 8) & 0xFF);
    buffer.buffer[buffer.offset++] = (byte) (size & 0xFF);

    // Write the message data
    System.arraycopy(data, 0, buffer.buffer, buffer.offset, size);
    buffer.offset += size;
    buffer.start = buffer.offset;

    out.write(buffer.buffer, 0, buffer.offset);
    buffer.offset = 0;

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (message == null) {
        throw new IllegalArgumentException("message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("schema cannot be null");
    }
    if (out == null) {
        throw new IllegalArgumentException("out cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("buffer cannot be null");
    }

    byte[] data = schema.toByteArray(message);
    int size = data.length;

    if (size > 0x7fffffffL) {
        throw new IllegalArgumentException("Message too large");
    }

    int written = 0;
    written += CodedOutputStream.computeRawVarint32Size(size);
    written += out.write(CodedOutputStream.encodeZigZag32(size)) + data.length;
    out.flush();

    return written;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    int size = data.length;
    Varint32.write32(out, size);
    out.write(data, 0, size);
    return size;
}

