static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }

    int year = (int) (timeBucket / 10000);
    int month = (int) (timeBucket % 10000 / 100);
    int day = (int) (timeBucket % 100);

    day = (day - 1) / dayStep * dayStep + 1;

    if (day == 0) {
        month--;
        if (month == 0) {
            year--;
            month = 12;
        }
        day = getDaysInMonth(year, month);
    }

    return year * 10000 + month * 100 + day;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 10000;
    long month = timeBucket % 10000 / 100;
    long day = timeBucket % 100;

    if (dayStep > 0) {
        day -= day % dayStep + (day % dayStep != 0 ? dayStep : 0);
    }

    return year * 10000 + month * 100 + day;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    return (timeBucket / dayStep) * dayStep;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long dayOffset = (timeBucket % 10000) / 10; // Get the day part (DD)
    long day = dayOffset - (dayOffset + dayStep - 1) % dayStep; // Calculate the new day part
    return timeBucket - dayOffset * 10 + day * 10; // Reformat the time bucket
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    switch (dayStep) {
        case 11:
            return timeBucket - timeBucket % 100;
        case 12:
            return timeBucket - timeBucket % 1000 + 200;
        case 13:
            return timeBucket - timeBucket % 1000;
        default:
            throw new IllegalArgumentException("Unsupported dayStep: " + dayStep);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len && i < str.length(); i++) {
        char c = str.charAt(i);
        if ((c & 0x80) == 0) {
            size += 1;
        } else if ((c & 0xE0) == 0xC0) {
            size += 2;
        } else if ((c & 0xF0) == 0xE0) {
            size += 3;
        } else if ((c & 0xF8) == 0xF0) {
            size += 4;
        } else if ((c & 0xFC) == 0xF8) {
            size += 5;
        } else if ((c & 0xFE) == 0xFA) {
            size += 6;
        }
    }
    return size;
}

