public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    try {
        byte[] bytes = str.toString().getBytes(StandardCharsets.UTF_8);
        int length = bytes.length;
        int bufferSize = lb.getBuffer().capacity();
        int position = lb.position();

        if (position + length > bufferSize) {
            lb = session.ensureCapacity(lb, length);
        }

        ByteBuffer buffer = lb.getBuffer();
        buffer.position(position);
        buffer.put(bytes);

        lb.position(position + length);
        return lb;
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("UTF-8 encoding not supported", e);
    }
}

