private static File[] classPath() {
    try {
        List<File> pathList = new ArrayList<>();
        ClassLoader classLoader = ClassLoader.getSystemClassLoader();
        Enumeration<URL> resources = classLoader.getResources("");
        while (resources.hasMoreElements()) {
            URL resource = resources.nextElement();
            Path path = Paths.get(URLDecoder.decode(resource.getFile(), "UTF-8"));
            Files.walk(path)
                .filter(Files::isRegularFile)
                .map(Path::toFile)
                .forEach(pathList::add);
        }
        return pathList.toArray(new File[0]);
    } catch (Exception e) {
        e.printStackTrace();
        return new File[0];
    }
}

private static File[] classPath() {
    ClassLoader classLoader = ClassLoader.getSystemClassLoader();
    String classPath = classLoader.getResource("").getPath();
    String pathSeparator = System.getProperty("path.separator");
    return Arrays.stream(classPath.split(pathSeparator))
                .map(File::new)
                .toArray(File[]::new);
}

private static File[] classPath() {
    try {
        URLClassLoader classLoader = (URLClassLoader) ClassLoader.getSystemClassLoader();
        URL[] urls = classLoader.getURLs();
        File[] classPathElements = new File[urls.length];
        for (int i = 0; i < urls.length; i++) {
            classPathElements[i] = new File(urls[i].toURI());
        }
        return classPathElements;
    } catch (Exception e) {
        e.printStackTrace();
        return new File[0];
    }
}

