    Box2D box1 = new Box2D();
    Box2D box2 = new Box2D();
    box1.setXmin(box.getXmin());
    box1.setXmax(x);
    box1.setYmin(box.getYmin());
    box1.setYmax(box.getYmax());
    box2.setXmin(x);
    box2.setXmax(box.getXmax());
    box2.setYmin(box.getYmin());
    box2.setYmax(box.getYmax());
    return new Pair<>(box1, box2);
}

