    double x = box.getX();

    Box2D leftBox = new Box2D(x, box.getY(), halfWidth, box.getHeight());
    Box2D rightBox = new Box2D(x + halfWidth, box.getY(), halfWidth, box.getHeight());

    return new Pair<>(leftBox, rightBox);
}

