        return graph.createPath();
    }

    Iterator<E> iterator = tour.iterator();
    E firstEdge = iterator.next();
    V source = graph.getEdgeSource(firstEdge);
    V target = graph.getEdgeTarget(firstEdge);

    GraphPath<V,E> path = graph.createPath(source, target);
    path.addEdge(firstEdge);

    while (iterator.hasNext()) {
        E nextEdge = iterator.next();
        V lastVertex = path.getEndVertex();
        if (graph.getEdgeSource(nextEdge).equals(lastVertex)) {
            path.addEdge(nextEdge);
        } else if (graph.getEdgeTarget(nextEdge).equals(lastVertex)) {
            path.addEdge graph.getEdge(graph.getEdgeTarget(nextEdge), lastVertex);
        } else {
            throw new IllegalArgumentException("Tour graph is not connected.");
        }
    }

    return path;
}

