private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("The bounds list cannot be null or empty");
    }

    List<Integer> suffixSumList = new ArrayList<>(Collections.nCopies(bounds.size(), 0));
    long totalSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        if (bounds.get(i) < 0) {
            throw new IllegalArgumentException("All elements in the bounds list must be non-negative");
        }
        totalSum += bounds.get(i);
        suffixSumList.set(i, totalSum);
    }

    return new Pair<>(suffixSumList, totalSum);
}

