    }

    for (int i = 0; i < bounds.size(); i++) {
        long sum = 0;
        for (int j = i; j < bounds.size(); j++) {
            sum += bounds.get(j);
        }
        suffixSum.add((int) sum);
        totalSum += bounds.get(i);
