    }

    // Normalize paths to remove any trailing slashes
    path = path.endsWith("/") ? path.substring(0, path.length() - 1) : path;
    relativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;

    // Split paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Process relative path components
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (pathComponents.length > 1) {
                pathComponents = Arrays.copyOfRange(pathComponents, 0, pathComponents.length - 1);
            }
        } else if (!component.equals(".")) {
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = component;
        }
    }

    // Combine path components to form the result path
    return String.join("/", pathComponents);
}

