public int readTag() throws IOException {
    int value = readUInt32();
    if (value == 0) {
        return 0;
    }
    int tagWireType = value & 0x7;
    int tagFieldNumber = value >>> 3;
    if (tagWireType < 0 || tagWireType >= WireFormat.WIRETYPE_MAX) {
        throw new IOException("Invalid wire type for tag: " + value);
    }
    return tagFieldNumber * 1000 + tagWireType; // encoding field number and wire type as a single int
}

public int readTag() throws IOException {
    if (buffer_.remaining() < 1) {
        refillBuffer();
        if (buffer_.remaining() < 1) {
            return 0; // EOF
        }
    }
    int firstByte = buffer_.get() & 0xFF;
    int tag WireType type = firstByte & 0x7;
    int fieldNumber = firstByte >>> 3;
    if (fieldNumber == 0) {
        throw ProtobufInvalidProtocolBufferException.invalidTag();
    }
    return fieldNumber | type << 3;
}

